import { motion } from 'framer-motion';
import { Flame, Eye, ShieldCheck } from 'lucide-react';

const COLUMN_STYLE = {
  main: {
    badge: 'border-rose-400/20 bg-rose-500/15 text-rose-700',
    accent: 'from-rose-500/22 to-orange-500/10',
    title: '主线',
  },
  watch: {
    badge: 'border-amber-300/20 bg-amber-500/15 text-amber-700',
    accent: 'from-amber-400/22 to-yellow-300/10',
    title: '观察',
  },
  alive: {
    badge: 'border-emerald-300/20 bg-emerald-500/15 text-emerald-100',
    accent: 'from-emerald-400/22 to-cyan-400/10',
    title: '活口',
  },
};

function ThemeRow({ item, style }) {
  const reasons = Array.isArray(item?.reasons) ? item.reasons.slice(0, 3) : [];
  return (
    <div className="rounded-2xl border border-[var(--border-color)] bg-[var(--bg-surface)] px-3 py-3">
      <div className="flex items-start justify-between gap-3">
        <div>
          <div className={`inline-flex rounded-full border px-2 py-1 text-[11px] font-semibold ${style.badge}`}>
            {style.title}
          </div>
          <div className="mt-2 text-base font-semibold text-[var(--text-primary)]">{item.name}</div>
          <div className="mt-1 text-xs text-[var(--text-secondary)]">龙头股：{item.leader}</div>
        </div>
        <div className="text-right">
          <div className={`text-lg font-bold ${item.change > 0 ? 'text-emerald-600' : 'text-rose-600'}`}>
            {item.change > 0 ? '+' : ''}
            {item.change}%
          </div>
          <div className="text-xs text-[var(--text-secondary)]">涨幅</div>
        </div>
      </div>

      <div className="mt-3">
        <div className="flex items-center justify-between text-[11px] text-[var(--text-secondary)]">
          <span>强度</span>
          <span>{item.strength}%</span>
        </div>
        <div className="mt-2 h-2 rounded-full bg-[var(--bg-surface)]">
          <div
            className="h-2 rounded-full bg-gradient-to-r from-cyan-300 to-blue-500"
            style={{ width: `${item.strength}%` }}
          />
        </div>
      </div>

      <div className="mt-3 rounded-xl border border-[var(--border-color)] bg-[var(--bg-surface)] px-3 py-2 text-xs leading-5 text-[var(--text-secondary)]">
        {item.judgment || item.note || '情绪仍在上行，分歧后更适合低吸核心。'}
      </div>

      {reasons.length ? (
        <div className="mt-3">
          <div className="text-[11px] uppercase tracking-[0.16em] text-[var(--text-secondary)]">依据</div>
          <div className="mt-2 flex flex-wrap gap-2">
            {reasons.map((reason, index) => (
              <span
                key={`${item.name}-reason-${index}`}
                className="rounded-full border border-[var(--border-color)] bg-[var(--bg-surface)] px-2.5 py-1 text-[11px] text-[var(--text-primary)]"
              >
                {reason}
              </span>
            ))}
          </div>
        </div>
      ) : null}
    </div>
  );
}

function ThemeColumn({ title, items, state }) {
  const style = COLUMN_STYLE[state];
  const Icon = title === '主线' ? Flame : title === '观察' ? Eye : ShieldCheck;

  return (
    <motion.div
      whileHover={{ y: -2 }}
      className={`rounded-[24px] border border-[var(--border-color)] bg-gradient-to-br ${style.accent} p-4 ${
        state === 'main'
          ? 'shadow-[0_0_36px_rgba(249,115,22,0.14)]'
          : state === 'watch'
            ? 'shadow-[0_0_30px_rgba(250,204,21,0.08)]'
            : 'shadow-[0_0_30px_rgba(34,197,94,0.08)]'
      }`}
    >
      <div className="mb-4 flex items-center justify-between">
        <div className="flex items-center gap-2 text-[var(--text-primary)]">
          <Icon className="h-4 w-4 text-[var(--text-primary)]/90" />
          <div className="text-lg font-semibold">{title}</div>
        </div>
        <div className={`rounded-full border px-3 py-1 text-[11px] font-semibold ${style.badge}`}>{style.title}</div>
      </div>

      <div className="space-y-3">
        {(items || []).length ? (
          (items || []).map((item) => (
            <ThemeRow key={item.name} item={item} style={style} />
          ))
        ) : (
          <div className="rounded-2xl border border-[var(--border-color)] bg-[var(--bg-surface)] px-4 py-4 text-sm text-[var(--text-secondary)]">
            暂无板块数据
          </div>
        )}
      </div>
    </motion.div>
  );
}

function EvidenceStack({ title, items, tone = 'text-[var(--text-primary)]', emptyText = '暂无' }) {
  const rows = Array.isArray(items) ? items : [];

  return (
    <div className="rounded-2xl border border-[var(--border-color)] bg-[var(--bg-surface)] p-3">
      <div className="text-[11px] uppercase tracking-[0.22em] text-[var(--text-secondary)]">{title}</div>
      <div className={`mt-2 space-y-1.5 text-xs leading-5 ${tone}`}>
        {rows.length ? (
          rows.slice(0, 3).map((item, index) => {
            if (typeof item === 'string') {
              return (
                <div key={`${title}-${index}`} className="rounded-xl border border-[var(--border-color)] bg-[var(--bg-surface)] px-2.5 py-2">
                  {item}
                </div>
              );
            }

            const label = item?.name || item?.title || '项';
            const detail = item?.reason || item?.judgment || item?.value || '';
            const impact = item?.impact !== undefined ? `影响 ${item.impact > 0 ? '+' : ''}${item.impact}` : '';

            return (
              <div key={`${title}-${label}-${index}`} className="rounded-xl border border-[var(--border-color)] bg-[var(--bg-surface)] px-2.5 py-2">
                <div className="font-medium text-[var(--text-primary)]">{label}</div>
                {detail ? <div className="mt-0.5 text-[var(--text-secondary)]">{detail}</div> : null}
                {impact ? <div className="mt-0.5 text-[11px] text-[var(--text-secondary)]">{impact}</div> : null}
              </div>
            );
          })
        ) : (
          <div className="rounded-xl border border-[var(--border-color)] bg-[var(--bg-surface)] px-2.5 py-2 text-[var(--text-secondary)]">{emptyText}</div>
        )}
      </div>
    </div>
  );
}

function BattlefieldIntel({ cognition }) {
  const stageDrivers = cognition?.breakdown?.stage?.drivers || [];
  const themeSignals = cognition?.breakdown?.theme?.signals || cognition?.signals?.theme || [];
  const riskDrivers = cognition?.breakdown?.risk?.drivers || cognition?.warnings || [];

  return (
    <div className="mb-4 rounded-[24px] border border-cyan-400/12 bg-[var(--bg-surface)] p-4">
      <div className="mb-3 flex items-center justify-between gap-3">
        <div>
          <div className="text-[11px] font-semibold uppercase tracking-[0.28em] text-cyan-600/70">Battle Intel</div>
          <div className="mt-1 text-sm font-semibold text-[var(--text-primary)]">主线为什么这样判</div>
        </div>
        <div className="rounded-full border border-cyan-400/15 bg-cyan-50 px-3 py-1 text-[11px] font-semibold text-cyan-700">
          依据集中在这里
        </div>
      </div>

      <div className="grid gap-3 xl:grid-cols-3">
        <EvidenceStack title="阶段驱动" items={stageDrivers} tone="text-cyan-700" emptyText="暂无阶段驱动" />
        <EvidenceStack title="主线信号" items={themeSignals} tone="text-amber-700" emptyText="暂无主线信号" />
        <EvidenceStack title="风险约束" items={riskDrivers} tone="text-rose-700" emptyText="暂无风险约束" />
      </div>
    </div>
  );
}

export default function ThemeBattlefield({ themes, cognition, loading }) {
  const mainline = themes?.mainline || [];
  const watch = themes?.watch || [];
  const alive = themes?.alive || [];

  return (
    <motion.section
      id="theme-panel"
      initial={{ opacity: 0, y: 12 }}
      animate={{ opacity: 1, y: 0 }}
      transition={{ duration: 0.35, delay: 0.1 }}
      className="glass-card rounded-[28px] p-5"
    >
      <div className="mb-4 flex items-center justify-between">
        <div>
          <div className="text-sm font-semibold uppercase tracking-[0.24em] text-cyan-600/80">Theme Battlefield</div>
          <div className="mt-1 text-[18px] font-semibold text-[var(--text-primary)]">主线战场</div>
        </div>
      </div>

      {loading ? (
        <div className="grid gap-3 xl:grid-cols-[1.15fr_0.92fr_0.92fr]">
          {[...Array(3)].map((_, index) => (
            <div key={index} className="h-[320px] animate-pulse rounded-[24px] bg-[var(--bg-surface)]" />
          ))}
        </div>
      ) : (
        <>
          <BattlefieldIntel cognition={cognition} />
          <div className="grid gap-3 xl:grid-cols-[1.15fr_0.92fr_0.92fr]">
            <ThemeColumn title="主线" items={mainline} state="main" />
            <ThemeColumn title="观察" items={watch} state="watch" />
            <ThemeColumn title="活口" items={alive} state="alive" />
          </div>
        </>
      )}
    </motion.section>
  );
}
